    "occurrence": "W20+10",
    "loot": "1 Ration Fleisch, 2W20+30 Stacheln (FF-Probe, um sie inklusive Giftdrüse aus dem Tier zu ziehen) * Pro Angriff wirft ein Stachelschwein 1W3 Stacheln auf einen einzelnen Gegner. ** Verursacht ein Stachel Schaden, so kommt das Gift zur Wirkung (kumulativ): Stufe 6; Wirkung 1W3 SP, GE, KK –1 für eine halbe Stunde, sollte die GE oder die KK auf 0 fallen, so führt dies innerhalb einer Spielrunde zum Tod."
